package io.github.plrlr.autopilot.skills.evolved;

import io.github.plrlr.autopilot.plan.Option;
import io.github.plrlr.autopilot.skills.Fail;
import io.github.plrlr.autopilot.skills.FairProbe;
import net.minecraft.core.BlockPos;

import java.util.Set;

public class StoneByHand extends EvolvedSkill {
	private static final Set<String> STONE = Set.of("minecraft:stone", "minecraft:cobblestone", "minecraft:deepslate",
			"minecraft:cobbled_deepslate", "minecraft:andesite", "minecraft:diorite", "minecraft:granite",
			"minecraft:tuff");

	private int want;
	private int beforeStone, beforeCobble;
	private BlockPos target;
	private int targetTicks;
	private int digDown;
	private int startY;
	private int idle;

	public static Option offer(Context c) {
		if (!"collect".equals(c.lastSkill()) || !"TIMEOUT".equals(c.lastCode())) return null;
		if (c.lastArg() == null || !c.lastArg().startsWith("stone")) return null;
		if (Player.gameSeconds() - c.lastEndSeconds() > 150) return null;
		if (Player.inWater() || Player.inLava() || !"minecraft:overworld".equals(Player.dimension()) && Player.dimension() != null && Player.dimension().contains("nether")) return null;
		if (Player.count("pickaxe") <= 0) return null;
		return new Option("stone_by_hand", c.lastArg(), "collect stone timed out: mine stone in reach by hand");
	}

	@Override
	public String name() { return "stone_by_hand"; }

	@Override
	protected void start() {
		want = 1;
		if (arg != null) {
			String[] parts = arg.split(":");
			if (parts.length > 1) {
				try { want = Math.max(1, Integer.parseInt(parts[1].trim())); } catch (NumberFormatException e) { want = 1; }
			}
		}
		want = Math.min(want, 24);
		beforeStone = Player.count("stone");
		beforeCobble = Player.count("cobblestone");
		startY = Player.feet().getY();
		timeoutTicks = 20 * 90;
		Player.stopWalking();
	}

	private int gained() {
		return Math.max(Player.count("stone") - beforeStone, Player.count("cobblestone") - beforeCobble);
	}

	private static boolean isStone(BlockPos p) {
		String id = Player.blockIfVisible(p);
		return id != null && STONE.contains(id);
	}

	private BlockPos findStone() {
		BlockPos f = Player.feet();
		BlockPos best = null;
		double bestD = Double.MAX_VALUE;
		double r = Math.min(4.5, Player.reach());
		for (int dy = -2; dy <= 3; dy++)
			for (int dx = -4; dx <= 4; dx++)
				for (int dz = -4; dz <= 4; dz++) {
					BlockPos p = f.offset(dx, dy, dz);
					double d = Player.pos().add(0, 1.6, 0).distanceTo(net.minecraft.world.phys.Vec3.atCenterOf(p));
					if (d > r || d >= bestD) continue;
					// don't mine the block we stand on (falls) unless nothing else
					if (p.equals(f.below())) continue;
					if (!isStone(p) || FairProbe.lavaSeenNear(p)) continue;
					best = p;
					bestD = d;
				}
		return best;
	}

	@Override
	protected void tick() {
		int got = gained();
		if (got >= want) { done("mined " + got + " stone by hand"); return; }
		if (Player.inLava()) { fail(Fail.HAZARD, "in lava"); return; }
		if (Player.inWater()) { fail(Fail.WRONG_PLACE, "in water"); return; }
		if (target != null) {
			targetTicks++;
			String id = Player.blockIfVisible(target);
			boolean gone = id == null ? false : (id.equals("minecraft:air") || id.equals("minecraft:cave_air"));
			if (gone || targetTicks > 20 * 6 || (id == null && targetTicks > 10)) {
				Player.releaseAll();
				target = null;
				return;
			}
			Player.holdBestToolFor(target);
			Player.lookAt(target);
			Player.mine(target);
			return;
		}
		if (ticks % 4 != 0) return;
		BlockPos s = findStone();
		if (s != null) {
			target = s;
			targetTicks = 0;
			idle = 0;
			return;
		}
		// No stone in reach: dig straight down a few blocks through dirt to reach it.
		if (!Player.onGround()) return;
		BlockPos below = Player.feet().below();
		String id = Player.blockIfVisible(below);
		if (startY - Player.feet().getY() >= 6 || digDown >= 8) {
			fail(Fail.NOT_FOUND, "no stone in reach after digging " + (startY - Player.feet().getY()) + " down (got " + got + ")");
			return;
		}
		if (id == null) {
			if (++idle > 10) fail(Fail.NOT_FOUND, "can't see the ground below");
			return;
		}
		if (FairProbe.lavaSeenNear(below) || id.contains("water") || id.contains("lava") || id.contains("bedrock")) {
			fail(Fail.HAZARD, "won't dig down into " + id);
			return;
		}
		digDown++;
		target = below;
		targetTicks = 0;
	}
}
